lor:#829082;font-size:9px;text-transform:uppercase;letter-spacing:.8px;font-weight:800}.player-name{font-weight:700}.player-meta{font-size:9px;color:var(--muted);margin-top:3px}.rating{font:700 12px var(--display);color:var(--green)}.table-wrap{overflow:auto}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.field{display:grid;gap:7px}.field label{font-size:10px;color:#a7b3a6;font-weight:700}.field input,.field select{background:#101812;border:1px solid #344235;color:var(--text);border-radius:10px;padding:11px 12px;width:100%;outline:none}.field input:focus,.field select:focus{border-color:var(--green)}.field small{color:#7e8c80;font-size:10px}.radio-row{display:flex;gap:8px;flex-wrap:wrap}.radio-chip{display:flex;gap:7px;align-items:center;padding:9px 11px;background:#111a13;border:1px solid #344235;border-radius:9px;font-size:11px}.radio-chip input{accent-color:var(--green)}.empty{text-align:center;padding:50px 20px;color:var(--muted)}.empty .empty-icon{font-size:37px;margin-bottom:12px}.empty h2{color:var(--text);margin:0 0 7px}.empty p{max-width:400px;margin:0 auto 17px;font-size:12px;line-height:1.55}.modal-backdrop{position:fixed;inset:0;background:#050906c9;backdrop-filter:blur(8px);z-index:10;display:grid;place-items:center;padding:16px}.modal{width:min(650px,100%);max-height:92vh;overflow:auto;background:#18231b;border:1px solid #3a493c;border-radius:20px;padding:23px;box-shadow:0 20px 90px #0009}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px}.modal-head h2{font:700 22px var(--display);margin:0}.modal-head p{color:var(--muted);font-size:11px;margin:5px 0 0}.modal-close{border:0;background:#29362c;border-radius:9px;width:32px;height:32px;font-size:18px}.modal-foot{display:flex;justify-content:space-between;margin-top:20px;gap:8px}.toast{position:fixed;bottom:22px;right:22px;z-index:20;background:#d5fa8c;color:#182114;padding:12px 17px;border-radius:11px;font-weight:800;box-shadow: