const KEY='touchline-careers-v1';let db=loadDB(),activeSlot=null,state=null,route='dashboard',rosterTab='all',marketTab='all',modal=null,matchLog=[];
function loadDB(){try{return JSON.parse(localStorage.getItem(KEY))||{saves:{},settings:{sound:true,matchLength:5}}}catch{return{saves:{},settings:{sound:true,matchLength:5}}}}
function persist(){localStorage.setItem(KEY,JSON.stringify(db))}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(n){let a=Math.abs(n);return a>=1e6?`€${(n/1e6).toFixed(1)}m`:a>=1000?`€${Math.round(n/1000)}k`:`€${n}`}
function initials(s){return s.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function clubData(key){return LEAGUES[key]}
function createLeague(key){let league=LEAGUES[key];return league.clubs.map((c,i)=>({id:`${key}-${i}`,name:c[0],short:c[1],color:c[2],stadium:c[3],capacity:c[4],rep:c[5],budget:(c[5]*c[5]*9000),wage:(c[5]*c[5]*120),players:createRoster(c[0],c[5],i),pts:0,w:0,d:0,l:0,gf:0,ga:0,form:[]}))}
function createRoster(club,rep,seed){let arr=[];for(let i=0;i<18;i++){let pos=POS[i],base=rep-10+(i<11?4:0)+Math.round(Math.sin((i+seed)*4.7)*7),age=18+((i*7+seed*3)%17),ovr=Math.max(47,Math.min(89,base+Math.round(Math.random()*5))),potential=Math.max(ovr,Math.min(94,ovr+Math.round(Math.random()*14)));arr.push({id:`${seed}-${i}-${Math.random().toString(36).slice(2,6)}`,name:`${FIRST_NAMES[(i*3+seed*5)%FIRST_NAMES.length]} ${LAST_NAMES[(i*7+seed*2)%LAST_NAMES.length]}`,pos,age,ovr,potential,form:Math.round(5+Math.random()*3),fitness:85+Math.round(Math.random()*15),value:Math.round((ovr*ovr*120)*(age<22?1.35:age>31?.65:1)),wage:Math.round(ovr*ovr*2.7),goals:0,apps:0,starter:i<11})}return arr}
function schedule(){let ids=state.teams.map(t=>t.id),rot=ids.slice(),rounds=[];if(rot.length%2)rot.push(null);let n=rot.length;for(let r=0;r<n-1;r++){let games=[];for(let i=0;i<n/2;i++){let a=rot[i],b=rot[n-1-i];if(a&&b){if(r%2)[a,b]=[b,a];games.push({home:a,away:b,played:false,score:null})}}rounds.push(games);rot.splice(1,0,rot.pop())}let second=rounds.map((g,r)=>g.map(x=>({home:x.away,away:x.home,played:false,score:null})));return rounds.concat(second)}
function newCareer(form){let key=form.league,teams=createLeague(key),team=teams.find(t=>t.name===form.club);let now=new Date();let today=`${form.year||2026}-07-01`;state={manager:{name:form.manager,nationality:form.nationality,age:+form.age,appearance:form.appearance,experience:form.experience,rep:form.experience==='Lenda'?64:form.experience==='Experiente'?48:form.experience==='Promissor'?34:22,popularity:36,licenses:form.experience==='Lenda'?3:form.experience==='Experiente'?2:1,history:[],titles:0,wins:0,draws:0,losses:0,salary:18000,club:team.name},club:team.id,league:key,teams,round:0,matchday:1,calendar:schedule(),date:today,season:2026,formation:'4-3-3',tactic:'Equilibrado',mentality:'Equilibrada',contract:{years:2,salary:18000},difficulty:form.difficulty,realism:form.realism,matchLength:+form.matchLength,budget:team.budget,news:[{date:today,type:'clube',title:`${team.name} apresenta ${form.manager}`,body:`O novo treinador inicia um projeto de ${form.experience.toLowerCase()} no ${team.name}. A expectativa da diretoria é uma temporada competitiva.`}],offers:[],messages:[],history:[],settings:{},lastMatch:null,transfers:[],sacked:false};state.roster=team.players;state.available=makeMarket(teams);state.lineup=team.players.slice(0,11).map(p=>p.id);state.objective=team.rep>82?'Brigar pelo título':team.rep>76?'Classificar para competição continental':'Terminar na metade de cima';state.contract.years=2;return state}
function makeMarket(teams){let all=[];teams.forEach(t=>t.players.forEach(p=>{if(Math.random()<.58)all.push({...p,club:t.name,clubId:t.id,price:Math.round(p.value*(.85+Math.random()*.55)),id:`m-${p.id}`} )}));return all.sort((a,b)=>b.ovr-a.ovr)}
function currentClub(){return state?.teams.find(t=>t.id===state.club)}
function nextGame(){if(!state)return null;for(let r=state.round;r<state.calendar.length;r++){let g=state.calendar[r].find(x=>x.home===state.club||x.away===state.club);if(g&&!g.played)return g}return null}
function opponentOf(g){let id=g.home===state.club?g.away:g.home;return state.teams.find(t=>t.id===id)}
function clubById(id){return state.teams.find(t=>t.id===id)}
function dateText(date=state?.date){return new Date(`${date}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})}
function toast(msg,error=false){let root=document.getElementById('toast-root');root.innerHTML=`<div class="toast ${error?'error':''}">${esc(msg)}</div>`;setTimeout(()=>root.innerHTML='',2800)}
function save(){if(!state||!activeSlot)return;db.saves[activeSlot]={state,updated:new Date().toISOString()};persist()}
function startSave(form,slot){state=newCareer(form);activeSlot=slot;db.saves[slot]={state,updated:new Date().toISOString()};persist();route='dashboard';render();toast('Carreira iniciada. Boa temporada!')}
function setRoute(r){route=r;modal=null;render()}
function rankTeams(){return [...state.teams].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf)}
function shortDate(){return new Date(`${state.date}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}
function addDays(n){let d=new Date(`${state.date}T12:00:00`);d.setDate(d.getDate()+n);state.date=d.toISOString().slice(0,10)}
function playerById(id){return state.roster.find(p=>p.id===id)}
function teamPower(team){let players=team.players;let avg=players.slice(0,11).reduce((a,p)=>a+p.ovr,0)/11;return avg*.72+team.rep*.28}
function simScore(home,away){let diff=teamPower(home)-teamPower(away),homeAdv=home.id===state.club?2.3:1.9;let lamH=Math.max(.35,1.35+(diff+homeAdv)/16),lamA=Math.max(.3,1.15-(diff+homeAdv)/17);function poisson(l){let L=Math.exp(-l),k=0,p=1;do{k++;p*=Math.random()}while(p>L);return k-1}return[Math.min(6,poisson(lamH)),Math.min(6,poisson(lamA))]}
function applyResult(game,h,a){game.played=true;game.score=[h,a];let home=clubById(game.home),away=clubById(game.away);home.gf+=h;home.ga+=a;away.gf+=a;away.ga+=h;if(h>a){home.pts+=3;home.w++;away.l++;home.form.unshift('W');away.form.unshift('L')}else if(h<a){away.pts+=3;away.w++;home.l++;away.form.unshift('W');home.form.unshift('L')}else{home.pts++;away.pts++;home.d++;away.d++;home.form.unshift('D');away.form.unshift('D')}home.form=home.form.slice(0,5);away.form=away.form.slice(0,5)}
function logEvent(text){matchLog.unshift(text)}

