function upcomingFixtures(n=8){let matches=[];state.calendar.forEach((round,i)=>round.forEach(g=>{if((g.home===state.club||g.away===state.club)&&!g.played)matches.push({g,i})}));return matches.slice(0,n).map(({g,i})=>{let opponent=opponentOf(g);return `<div class="fixture"><div class="fixture-date">ROD. ${i+1}<br>${i===state.round?'PRÓXIMA':'+'+(i-state.round)+' sem'}</div><div class="fixture-clubs">${g.home===state.club?badge(currentClub(),'sm'):badge(opponent,'sm')}<b>${g.home===state.club?esc(currentClub().name):esc(opponent.name)}</b><span style="color:#748174">×</span><b>${g.away===state.club?esc(currentClub().name):esc(opponent.name)}</b>${g.away===state.club?badge(currentClub(),'sm'):badge(opponent,'sm')}</div><span class="tag">${g.home===state.club?'CASA':'FORA'}</span></div>`}).join('')||'<div class="empty" style="padding:20px">Nenhum jogo pendente.</div>'}
function squadPage(){let positions=['GOL','ZAG','LD','LE','VOL','MC','MEI','PD','PE','ATA'];let filtered=state.roster.filter(p=>rosterTab==='all'||p.pos===rosterTab).sort((a,b)=>b.ovr-a.ovr);return `${header('Elenco',`${state.roster.length} atletas · Folha salarial ${money(state.roster.reduce((s,p)=>s+p.wage,0))}`,`<button class="btn btn-primary" onclick="setRoute('tactics')">MONTAR TIME →</button>`)}<div class="page-tabs"><button class="tab ${rosterTab==='all'?'active':''}" onclick="rosterTab='all';render()">Todos (${state.roster.length})</button>${positions.map(pos=>`<button class="tab ${rosterTab===pos?'active':''}" onclick="rosterTab='${pos}';render()">${pos} (${state.roster.filter(p=>p.pos===pos).length})</button>`).join('')}</div><div class="card"><div class="card-head"><h2>Jogadores</h2><span class="tag">ELENCO PRINCIPAL</span></div><div class="player-row header"><span>POS</span><span>JOGADOR</span><span>IDADE</span><span>GER</span><span>VALOR</span><span class="hide-mobile">CONTRATO</span><span class="hide-mobile">STATUS</span></div>${filtered.map(p=>`<div class="player-row"><span class="tag">${p.pos}</span><div><div class="player-name">${esc(p.name)}</div><div class="player-meta">${p.apps} partidas · ${p.goals} gols</div></div><span>${p.age}</span><span class="rating">${p.ovr}</span><span>${money(p.value)}</span><span class="hide-mobile">${money(p.wage)}/sem</span><button class="btn ${state.lineup.includes(p.id)?'btn-primary':''}" style="padding:6px 8px;font-size:9px" onclick="toggleStarter('${p.id}')">${state.lineup.includes(p.id)?'TITULAR':'RESERVA'}</button></div>`).join('')||'<div class="empty">Nenhum atleta nesta posição.</div>'}</div><div class="grid grid-3" style="margin-top:15px"><div class="stat-card"><div class="stat-label">MÉDIA DO ELENCO</div><div class="stat-value">${Math.round(state.roster.reduce((a,p)=>a+p.ovr,0)/state.roster.length)}</div><div class="stat-note">Overall geral</div></div><div class="stat-card"><div class="stat-label">VALOR DO ELENCO</div><div class="stat-value">${money(state.roster.reduce((a,p)=>a+p.value,0))}</div><div class="stat-note">Estimativa de mercado</div></div><div class="stat-card"><div class="stat-label">FOLHA SALARIAL</div><div class="stat-value">${money(state.roster.reduce((a,p)=>a+p.wage,0))}</div><div class="stat-note">Por semana</div></div></div>`}
function toggleStarter(id){let p=playerById(id);if(state.lineup.includes(id)){if(state.lineup.length<=7)return toast('Mantenha pelo menos 7 jogadores na equipe.',true);state.lineup=state.lineup.filter(x=>x!==id);p.starter=false}else{if(state.lineup.length>=11)return toast('A equipe titular já tem 11 jogadores.',true);state.lineup.push(id);p.starter=true}save();render()}
function tacticsPage(){let groups=Object.entries(FORMATIONS),lineup=state.lineup.map(playerById).filter(Boolean);let rows=state.formation.split('-').map(x=>+x);let byLines=[];let cursor=0;rows.forEach((n,idx)=>{let picks=lineup.slice(cursor,cursor+n);cursor+=n;byLines.push(picks)});let bench=state.roster.filter(p=>!state.lineup.includes(p.id));return `${header('Táticas','Escolha a formação e a abordagem para sua equipe.',`<button class="btn btn-primary" onclick="save();toast('Táticas salvas.')">SALVAR TÁTICAS</button>`)}<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Campo tático</h2><span class="tag green">${state.formation}</span></div><div class="pitch"><div class="pitch-line">${byLines.map((line,idx)=>`<div class="pitch-row">${line.map(p=>`<div class="pitch-player" onclick="openPlayer('${p.id}')"><div class="pitch-shirt">${p.pos}</div><small>${esc(p.name.split(' ').slice(-1)[0])}</small><em>${p.ovr} GER</em></div>`).join('')||'<span class="tag">Vazio</span>'}</div>`).join('')}</div></div><p class="stat-note" style="margin-top:12px">Toque em um jogador para ver seus detalhes. A equipe titular é definida no menu Elenco.</p></div><div class="card"><div class="card-head"><h2>Plano de jogo</h2></div><div class="field"><label>FORMAÇÃO</label><div class="page-tabs">${groups.map(([f])=>`<button class="tab ${state.formation===f?'active':''}" onclick="state.formation='${f}';save();render()">${f}</button>`).join('')}</div></div><div class="field" style="margin-top:15px"><label>ESTILO DE JOGO</label><select onchange="state.tactic=this.value;save()">${['Equilibrado','Posse de bola','Contra-ataque','Pressão alta','Jogo direto'].map(x=>`<option ${state.tactic===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" style="margin-top:15px"><label>MENTALIDADE</label><select onchange="state.mentality=this.value;save()">${['Defensiva','Equilibrada','Ofensiva','Muito ofensiva'].map(x=>`<option ${state.mentality===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="card" style="padding:13px;margin-top:18px;background:#111a13"><div class="card-head" style="margin-bottom:7px"><h2 style="font-size:13px">Força da equipe</h2><b class="rating">${Math.round(lineup.reduce((a,p)=>a+p.ovr,0)/Math.max(1,lineup.length))}</b></div>${[['Ataque',lineup.filter(p=>['ATA','PD','PE','MEI'].includes(p.pos))],['Meio-campo',lineup.filter(p=>['VOL','MC','MEI'].includes(p.pos))],['Defesa',lineup.filter(p=>['ZAG','LD','LE','GOL'].includes(p.pos))]].map(([l,ps])=>{let val=Math.round(ps.reduce((a,p)=>a+p.ovr,0)/Math.max(ps.length,1));return `<div class="bar-row"><span>${l}</span><span class="bar"><i style="width:${val}%"></i></span><b>${val}</b></div>`}).join('')}</div><div style="margin-top:15px"><span class="tag">${lineup.length} titulares selecionados</span><span class="tag" style="margin-left:5px">${bench.length} reservas</span></div></div></div>`}
function openPlayer(id){let p=playerById(id);if(!p)return;modal={type:'player',id};render()}

