iv class="card"><div class="card-head"><h2>Histórico da carreira</h2></div>${state.manager.history.length?state.manager.history.map(h=>`<div class="fixture"><span class="tag">${h.season}</span><div><b>${esc(h.club)}</b><div class="stat-note">${esc(h.competition)} · ${h.place}º lugar</div></div><b class="rating">${h.pts} pts</b></div>`).join(''):'<div class="empty" style="padding:28px"><div class="empty-icon">◷</div><h2>Comece sua jornada</h2><p>O histórico e os títulos aparecerão conforme você avança as temporadas.</p></div>'}</div></div>`}
