function showCareerMenu(){if(!confirm('Voltar ao menu principal? O progresso é salvo automaticamente.'))return;save();state=null;activeSlot=null;render()}
function settingsPage(){return `${header('Configurações','Personalize sua experiência de jogo.') }<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Preferências de jogo</h2></div><div class="settings-item"><div><b>Duração da partida</b><small>Define o ritmo da simulação</small></div><select style="background:#101812;color:white;border:1px solid #344235;padding:8px;border-radius:8px" onchange="db.settings.matchLength=+this.value;persist()"><option value="3" ${db.settings.matchLength===3?'selected':''}>Rápida · 3 min</option><option value="5" ${db.settings.matchLength===5||!db.settings.matchLength?'selected':''}>Normal · 5 min</option><option value="8" ${db.settings.matchLength===8?'selected':''}>Completa · 8 min</option></select></div><div class="settings-item"><div><b>Efeitos sonoros</b><small>Feedback de interface (sons a implementar)</small></div><button class="pill-toggle ${db.settings.sound?'active':''}" onclick="db.settings.sound=!db.settings.sound;persist();render()">${db.settings.sound?'ATIVADO':'DESATIVADO'}</button></div><div class="settings-item"><div><b>Privacidade dos dados</b><small>Carreiras ficam salvas apenas neste navegador.</small></div><span class="tag green">LOCAL</span></div></div><div class="card"><div class="card-head"><h2>Arquivos de carreira</h2></div><p class="stat-note" style="line-height:1.6">Você pode manter vários arquivos de carreira independentes. Os dados ficam no armazenamento local deste navegador; limpar os dados do navegador poderá apagá-los.</p><button class="btn" onclick="openModal('load')">GERENCIAR ARQUIVOS</button><button class="btn btn-danger" style="margin-left:7px" onclick="exportSave()">EXPORTAR ARQUIVO</button></div></div>`}
function exportSave(){if(!state)return;let blob=new Blob([JSON.stringify({state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`touchline-${state.manager.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}.json`;a.click();URL.revokeObjectURL(a.href);toast('Arquivo exportado.')}
function modalHTML(){let type=modal.type;let content='';if(type==='new')content=newCareerForm();else if(type==='load')content=loadForm();else if(type==='settings')content=settingsForm();else if(type==='credits')content=`<div class="modal-head"><div><h2>Créditos</h2><p>Obrigado por jogar Touchline.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="inbox-item"><b>TOUCHLINE · FOOTBALL CAREER MANAGER</b><p>Jogo independente de gestão esportiva. Clubes e competições apresentados são exemplos de referência; atletas são gerados proceduralmente e não são elencos licenciados. Nenhuma afiliação com ligas, federações ou clubes.</p></div><button class="btn btn-primary" onclick="closeModal()">VOLTAR</button>`;else if(type==='player')content=playerModal();else if(type==='finance')content=financeModal();else if(type==='contract')content=contractModal();else if(type==='job')content=jobModal();else if(type==='match')content=matchModal();return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal">${content}</div></div>`}
function closeModal(){modal=null;render()}
function newCareerForm(){let leagues=Object.keys(LEAGUES);return `<div class="modal-head"><div><div class="eyebrow">NOVA JORNADA</div><h2>Crie sua carreira</h2><p>Escolha seu perfil e assuma o comando.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form id="new-form" onsubmit="submitCareer(event)"><div class="form-grid"><div class="field"><label>NOME DO TREINADOR</label><input name="manager" required maxlength="30" placeholder="Ex.: Alex Costa" value="Alex Costa"></div><div class="field"><label>NACIONALIDADE</label><select name="nationality"><option>Brasil</option><option>Portugal</option><option>Argentina</option><option>Inglaterra</option><option>Espanha</option><option>Itália</option><option>França</option><option>Alemanha</option><option>Japão</option></select></div><div class="field"><label>IDADE</label><input name="age" type="number" min="18" max="80" value="38" required></div><div class="field"><label>APARÊNCIA</label><select name="appearance"><option>Clássico</option><option>Moderno</option><option>Jovem</option><option>Veterano</option></select></div><div class="field"><label>EXPERIÊNCIA</label><select name="experience"><option>Iniciante</option><option>Promissor</option><option>Experiente</option><option>Lenda</option></select></div><div class="field"><label>DIFICULDADE</label><select name="difficulty"><option>Normal</option><option>Desafio</option><option>Realista</option></select></div><div class="field"><label>PAÍS E DIVISÃO</label><select name="league" id="league-select" onchange="updateClubs()">${leagues.map(k=>`<option value="${esc(k)}">${esc(k.replace('|',' · '))}</option>`).join('')}</select><small>Banco expansível · ligas com clubes reais cadastrados</small></div><div class="field"><label>CLUBE INICIAL</label><select name="club" id="club-select">${LEAGUES[leagues[0]].clubs.map(c=>`<option>${esc(c[0])}</option>`).join('')}</select></div><div class="field"><label>REALISMO DAS NEGOCIAÇÕES</label><select name="realism"><option value="Realista">Realista</option><option value="Flexível">Flexível</option><option value="Rigoroso">Rigoroso</option></select></div><div class="field"><label>DURAÇÃO DA PARTIDA</label><select name="matchLength"><option value="3">Rápida · 3 minutos</option><option value="5" selected>Normal · 5 minutos</option><option value="8">Completa · 8 minutos</option></select></div></div><div class="modal-foot"><span class="stat-note">O progresso será salvo automaticamente.</span><button class="btn btn-primary" type="submit">COMEÇAR CARREIRA →</button></div></form>`}
function updateClubs(){let key=document.getElementById('league-select').value,sel=document.getElementById('club-select');sel.innerHTML=LEAGUES[key].clubs.map(c=>`<option>${esc(c[0])}</option>`).join('')}
function submitCareer(e){e.preventDefault();let form=Object.fromEntries(new FormData(e.target).entries()),slot=`career-${Date.now()}`;form.year=new Date().getFullYear();db.settings.matchLength=+form.matchLength;persist();startSave(form,slot)}
function loadForm(){let saves=Object.entries(db.saves);return `<div class="modal-head"><div><div class="eyebrow">GERENCIAR ARQUIVOS</div><h2>Carregar carreira</h2><p>Selecione um arquivo salvo neste dispositivo.</p></div><button class="modal-close" onclick="closeModal()">×</button></div>${saves.length?saves.sort((a,b)=>b[1].updated.localeCompare(a[1].updated)).map(([key,data])=>`<div class="inbox-item" style="display:flex;align-items:center;justify-content:space-between;gap:12px"><div><b>${esc(data.state.manager.name)}</b><p style="margin:5px 0 0">${esc(data.state.club?data.state.teams.find(t=>t.id===data.state.club)?.name:'Sem clube')} · Temporada ${data.state.season} · ${dateText(data.state.date)}</p></div><div style="display:flex;gap:6px"><button class="btn btn-primary" onclick="loadSave('${esc(key)}')">CARREGAR</button><button class="btn btn-danger" onclick="deleteSave('${esc(key)}')">✕</button></div></div>`).join(''):'<div class="empty"><div class="empty-icon">▣</div><h2>Nenhum arquivo salvo</h2><p>Inicie uma nova carreira para criar seu primeiro arquivo.</p></div>'}<div class="modal-foot"><button class="btn" onclick="closeModal()">FECHAR</button><button class="btn btn-primary" onclick="modal={type:'new'};render()">NOVA CARREIRA</button></div>`}
function deleteSave(k){if(confirm('Excluir este arquivo de carreira permanentemente?')){delete db.saves[k];persist();if(activeSlot===k){state=null;activeSlot=null}modal={type:'load'};render()}}
function settingsForm(){return `<div class="modal-head"><div><div class="eyebrow">PREFERÊNCIAS</div><h2>Configurações</h2><p>Defina o ritmo da partida e seus dados locais.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="settings-item"><div><b>Duração da partida</b><small>Tempo sugerido para cada partida</small></div><select id="setting-length" style="background:#101812;color:white;border:1px solid #344235;padding:8px;border-radius:8px"><option value="3" ${db.settings.matchLength===3?'selected':''}>3 min</option><option value="5" ${db.settings.matchLength===5||!db.settings.matchLength?'selected':''}>5 min</option><option value="8" ${db.settings.matchLength===8?'selected':''}>8 min</option></select></div><div class="settings-item"><div><b>Efeitos sonoros</b><small>Feedback de interface</small></div><button class="pill-toggle ${db.settings.sound?'active':''}" onclick="db.settings.sound=!db.settings.sound;persist();modal={type:'settings'};render()">${db.settings.sound?'ATIVADO':'DESATIVADO'}</button></div><p class="stat-note" style="line-height:1.55">Dados salvos localmente neste navegador. Recomendamos exportar seu arquivo de carreira ocasionalmente.</p><div class="modal-foot"><button class="btn" onclick="closeModal()">CANCELAR</button><button class="btn btn-primary" onclick="db.settings.matchLength=+document.getElementById('setting-length').value;persist();closeModal();toast('Configurações salvas.')">SALVAR</button></div>`}

