function teamPower(team){let players=team.players;let avg=players.slice(0,11).reduce((a,p)=>a+p.ovr,0)/11;return avg*.72+team.rep*.28}
function simScore(home,away){let diff=teamPower(home)-teamPower(away),homeAdv=home.id===state.club?2.3:1.9;let lamH=Math.max(.35,1.35+(diff+homeAdv)/16),lamA=Math.max(.3,1.15-(diff+homeAdv)/17);function poisson(l){let L=Math.exp(-l),k=0,p=1;do{k++;p*=Math.random()}while(p>L);return k-1}return[Math.min(6,poisson(lamH)),Math.min(6,poisson(lamA))]}
function applyResult(game,h,a){game.played=true;game.score=[h,a];let home=clubById(game.home),away=clubById(game.away);home.gf+=h;home.ga+=a;away.gf+=a;away.ga+=h;if(h>a){home.pts+=3;home.w++;away.l++;home.form.unshift('W');away.form.unshift('L')}else if(h<a){away.pts+=3;away.w++;home.l++;away.form.unshift('W');home.form.unshift('L')}else{home.pts++;away.pts++;home.d++;away.d++;home.form.unshift('D');away.form.unshift('D')}home.form=home.form.slice(0,5);away.form=away.form.slice(0,5)}
function logEvent(text){matchLog.unshift(text)}
function badge(team,cls=''){return `<span class="club-badge ${cls}" style="background:${esc(team.color)}">${esc(team.short)}</span>`}
function topbar(){let c=currentClub();return `<div class="topbar"><div class="crumb">TOUCHLINE <span style="color:#59665a"> / </span> <b>${esc(routeLabel())}</b></div><div class="top-actions"><span class="date-pill">◷ &nbsp;${dateText()}</span>${c?`<span class="cash-pill">${money(state.budget)}</span>`:''}<button class="icon-btn" onclick="openModal('settings')" aria-label="Configurações">⚙</button></div></div>`}
function routeLabel(){return ({dashboard:'Visão geral',squad:'Elenco',tactics:'Táticas',fixtures:'Calendário',table:'Classificação',market:'Transferências',inbox:'Central do clube',stats:'Estatísticas',editor:'Editor de elencos',settings:'Configurações'})[route]||'Football Career Manager'}
function sideNav(){return `<aside class="sidebar"><div class="brand"><div class="brandmark">⚽</div><div><strong>TOUCHLINE</strong><small>CAREER MANAGER</small></div></div><div class="nav-label">CLUBE</div><nav class="nav">${NAV.map(([id,ico,label])=>`<button class="${route===id?'active':''}" onclick="setRoute('${id}')"><span class="ico">${ico}</span>${label}</button>`).join('')}</nav><div class="nav-label" style="margin-top:19px">GERAL</div><nav class="nav"><button class="${route==='stats'?'active':''}" onclick="setRoute('stats')"><span class="ico">◫</span>Estatísticas</button><button onclick="showCareerMenu()"><span class="ico">↶</span>Trocar carreira</button></nav><div class="side-bottom"><div class="manager-mini"><div class="avatar">${state?esc(initials(state.manager.name)):'?'}</div><div><b>${state?esc(state.manager.name):'Sem treinador'}</b><small>${state?esc(currentClub()?.name||'Sem clube'):'Crie uma carreira'}</small></div></div></div></aside>`}
function header(title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${esc(currentClub()?.name||'TOUCHLINE MANAGER')}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function dashboard(){let c=currentClub(),game=nextGame(),opp=game?opponentOf(game):null,home=game?.home===state.club,rank=rankTeams(),place=rank.findIndex(t=>t.id===state.club)+1,played=c.w+c.d+c.l,playedGames=state.calendar.filter(r=>r.some(g=>g.played)).length;return `${header('Visão geral',`Temporada ${state.season} · ${state.league.split('|')[1]} · ${playedGames} rodadas disputadas`)}<section class="hero"><div class="hero-content"><div class="eyebrow">PRÓXIMO DESAFIO · RODADA ${state.matchday}</div><h2>${game?'Dia de jogo. Vamos, '+esc(c.name)+'.':'A temporada chegou ao fim.'}</h2><p>${game?`Prepare a equipe para ${home?'receber':'visitar'} ${esc(opp.name)}. A torcida espera uma grande atuação.`:'Revise seus resultados e prepare o próximo ano.'}</p>${game?`<div class="next-match"><button class="btn btn-primary" onclick="playMatch()">JOGAR PARTIDA &nbsp;→</button><span class="tag">${home?'CASA':'FORA'} · ${esc(opp.name)}</span></div>`:`<button class="btn btn-primary" onclick="advanceSeason()">COMEÇAR NOVA TEMPORADA</button>`}</div></section><div class="stats-row"><div class="stat-card"><div class="stat-label">POSIÇÃO NA LIGA</div><div class="stat-value">${place}<span style="font-size:12px;color:#859185">º / ${state.teams.length}</span></div><div class="stat-note good">${c.pts} pontos</div></div><div class="stat-card"><div class="stat-label">CAMPANHA</div><div class="stat-value">${c.w}<span style="color:#728073">-${c.d}-${c.l}</span></div><div class="stat-note">${played} partidas</div></div><div class="stat-card"><div class="stat-label">SALDO DE GOLS</div><div class="stat-value">${c.gf-c.ga>0?'+':''}${c.gf-c.ga}</div><div class="stat-note">${c.gf} marcados · ${c.ga} sofridos</div></div><div class="stat-card"><div class="stat-label">REPUTAÇÃO</div><div class="stat-value">${state.manager.rep}<span style="font-size:12px;color:#859185"> / 100</span></div><div class="stat-note good">${state.manager.popularity}% popularidade</div></div></div><div class="grid grid-2"><div class="card"><div class="card-head"><h2>Classificação</h2><button class="link-btn" onclick="setRoute('table')">VER TABELA →</button></div>${leagueTable(rank.slice(0,6),true)}</div><div class="card"><div class="card-head"><h2>Próximos jogos</h2><button class="link-btn" onclick="setRoute('fixtures')">CALENDÁRIO →</button></div>${upcomingFixtures(4)}</div></div><div class="grid grid-2" style="margin-top:16px"><div class="card"><div class="card-head"><h2>Notícias do clube</h2><button class="link-btn" onclick="setRoute('inbox')">CENTRAL →</button></div>${state.news.slice(0,3).map(n=>`<div class="news-item"><div class="news-kicker">${esc(n.type)} · ${dateText(n.date)}</div><b>${esc(n.title)}</b><p>${esc(n.body)}</p></div>`).join('')||'<p class="stat-note">Nenhuma novidade por enquanto.</p>'}</div><div class="card"><div class="card-head"><h2>Elenco principal</h2><button class="link-btn" onclick="setRoute('squad')">GERENCIAR →</button></div>${state.roster.slice().sort((a,b)=>b.ovr-a.ovr).slice(0,5).map(p=>`<div class="fixture"><span class="tag">${p.pos}</span><div><b>${esc(p.name)}</b><div class="stat-note">${p.age} anos · ${p.apps} jogos</div></div><b class="rating">${p.ovr}</b></div>`).join('')}</div></div>`}
function leagueTable(teams,compact=false){let rank=rankTeams();return `<div class="table-wrap"><table class="table"><thead><tr><th>Clube</th><th>J</th><th>V</th><th>E</th><th>D</th><th>SG</th><th>PTS</th>${compact?'':'<th>Forma</th>'}</tr></thead><tbody>${teams.map(t=>`<tr><td><span class="club-cell"><span class="position">${rank.indexOf(t)+1}</span>${badge(t,'sm')}<span>${esc(t.name)}</span>${t.id===state.club?'<span class="tag green">VOCÊ</span>':''}</span></td><td>${t.w+t.d+t.l}</td><td>${t.w}</td><td>${t.d}</td><td>${t.l}</td><td>${t.gf-t.ga>0?'+':''}${t.gf-t.ga}</td><td><b>${t.pts}</b></td>${compact?'':`<td><span class="form-dots">${(t.form.length?t.form:['-','-','-','-','-']).map(x=>`<span class="form-dot ${x==='W'?'w':x==='D'?'d':x==='L'?'l':''}">${x}</span>`).join('')}</span></td>`}</tr>`).join('')}</tbody></table></div>`}
function upcomingFixtures(n=8){let matches=[];state.calendar.forEach((round,i)=>round.forEach(g=>{if((g.home===state.club||g.away===state.club)&&!g.played)matches.push({g,i})}));return matches.slice(0,n).map(({g,i})=>{let opponent=opponentOf(g);return `<div class="fixture"><div class="fixture-date">ROD. ${i+1}<br>${i===state.round?'PRÓXIMA':'+'+(i-state.round)+' sem'}</div><div class="fixture-clubs">${g.home===state.club?badge(currentClub(),'sm'):badge(opponent,'sm')}<b>${g.home===state.club?esc(currentClub().name):esc(opponent.name)}</b><span style="color:#748174">×</span><b>${g.away===state.club?esc(currentClub().name):esc(opponent.name)}</b>${g.away===state.club?badge(currentClub(),'sm'):badge(opponent,'sm')}</div><span class="tag">${g.home===state.club?'CASA':'FORA'}</span></div>`}).join('')||'<div class="empty" style="padding:20px">Nenhum jogo pendente.</div>'}
function squadPage(){let positions=['GOL','ZAG','LD','LE','VOL','MC','MEI','PD','PE','ATA'];let filtered=state.roster.filter(p=>rosterTab==='all'||p.pos===rosterTab).sort((a,b)=>b.ovr-a.ovr);return `${header('Elenco',`${state.roster.length} atletas · Folha salarial ${money(state.roster.reduce((s,p)=>s+p.wage,0))}`,`<button class="btn btn-primary" onclick="setRoute('tactics')">MONTAR TIME →</button>`)}<div class="page-tabs"><button class="tab ${rosterTab==='all'?'active':''}" onclick="rosterTab='all';render()">Todos (${state.roster.length})</button>${positions.map(pos=>`<button class="tab ${rosterTab===pos?'active':''}" onclick="rosterTab='${pos}';render()">${pos} (${state.roster.filter(p=>p.pos===pos).length})</button>`).join('')}</div><div class="card"><div class="card-head"><h2>Jogadores</h2><span class="tag">ELENCO PRINCIPAL</span></div><div class="player-row header"><span>POS</span><span>JOGADOR</span><span>IDADE</span><span>GER</span><span>VALOR</span><span class="hide-mobile">CONTRATO</span><span class="hide-mobile">STATUS</span></div>${filtered.map(p=>`<div class="player-row"><span class="tag">${p.pos}</span><div><div class="player-name">${esc(p.name)}</div><div class="player-meta">${p.apps} partidas · ${p.goals} gols</div></div><span>${p.age}</span><span class="rating">${p.ovr}</span><span>${money(p.value)}</span><span class="hide-mobile">${money(p.wage)}/sem</span><button class="btn ${state.lineup.includes(p.id)?'btn-primary':''}" style="padding:6px 8px;font-size:9px" onclick="toggleStarter('${p.id}')">${state.lineup.includes(p.id)?'TITULAR':'RESERVA'}</button></div>`).join('')||'<div class="empty">Nenhum atleta nesta posição.</div>'}</div><div class="grid grid-3" style="margin-top:15px"><div class="stat-card"><div class="stat-label">MÉDIA DO ELENCO</div><div class="stat-value">${Math.round(state.roster.reduce((a,p)=>a+p.ovr,0)/state.roster.length)}</div><div class="stat-note">Overall geral</div></div><div class="stat-card"><div class="stat-label">VALOR DO ELENCO</div><div class="stat-value">${money(state.roster.reduce((a,p)=>a+p.value,0))}</div><div class="stat-note">Estimativa de mercado</div></div><div class="stat-card"><div class="stat-label">FOLHA SALARIAL</div><div class="stat-value">${money(state.roster.reduce((a,p)=>a+p.wage,0))}</div><div class="stat-note">Por semana</div></div></div>`}
function toggleStarter(id){let p=playerById(id);if(state.lineup.includes(id)){if(state.lineup.length<=7)return toast('Mantenha pelo menos 7 jogadores na equipe.',true);state.lineup=state.lineup.filter(x=>x!==id);p.starter=false}else{if(state.lineup.length>=11)return toast('A equipe titular já tem 11 jogadores.',true);state.lineup.push(id);p.starter=true}save();render()}
function tacticsPage(){let groups=Object.entries(FORMATIONS),lineup=state.lineup.map(playerById).filter(Boolean);let rows=state.formation.split('-').map(x=>+x);let byLines=[];let cursor=0;rows.forEach((n,idx)=>{let picks=lineup.slice(cursor,cursor+n);cursor+=n;byLines.push(picks)});let bench=state.roster.filter(p=>!state.lineup.includes(p.id));return `${header('Táticas','Escolha a formação e a abordagem para sua equipe.',`<button class="btn btn-primary" onclick="save();toast('Táticas salvas.')">SALVAR TÁTICAS</button>`)}<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Campo tático</h2><span class="tag green">${state.formation}</span></div><div class="pitch"><div class="pitch-line">${byLines.map((line,idx)=>`<div class="pitch-row">${line.map(p=>`<div class="pitch-player" onclick="openPlayer('${p.id}')"><div class="pitch-shirt">${p.pos}</div><small>${esc(p.name.split(' ').slice(-1)[0])}</small><em>${p.ovr} GER</em></div>`).join('')||'<span class="tag">Vazio</span>'}</div>`).join('')}</div></div><p class="stat-note" style="margin-top:12px">Toque em um jogador para ver seus detalhes. A equipe titular é definida no menu Elenco.</p></div><div class="card"><div class="card-head"><h2>Plano de jogo</h2></div><div class="field"><label>FORMAÇÃO</label><div class="page-tabs">${groups.map(([f])=>`<button class="tab ${state.formation===f?'active':''}" onclick="state.formation='${f}';save();render()">${f}</button>`).join('')}</div></div><div class="field" style="margin-top:15px"><label>ESTILO DE JOGO</label><select onchange="state.tactic=this.value;save()">${['Equilibrado','Posse de bola','Contra-ataque','Pressão alta','Jogo direto'].map(x=>`<option ${state.tactic===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" style="margin-top:15px"><label>MENTALIDADE</label><select onchange="state.mentality=this.value;save()">${['Defensiva','Equilibrada','Ofensiva','Muito ofensiva'].map(x=>`<option ${state.mentality===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="card" style="padding:13px;margin-top:18px;background:#111a13"><div class="card-head" style="margin-bottom:7px"><h2 style="font-size:13px">Força da equipe</h2><b class="rating">${Math.round(lineup.reduce((a,p)=>a+p.ovr,0)/Math.max(1,lineup.length))}</b></div>${[['Ataque',lineup.filter(p=>['ATA','PD','PE','MEI'].includes(p.pos))],['Meio-campo',lineup.filter(p=>['VOL','MC','MEI'].includes(p.pos))],['Defesa',lineup.filter(p=>['ZAG','LD','LE','GOL'].includes(p.pos))]].map(([l,ps])=>{let val=Math.round(ps.reduce((a,p)=>a+p.ovr,0)/Math.max(ps.length,1));return `<div class="bar-row"><span>${l}</span><span class="bar"><i style="width:${val}%"></i></span><b>${val}</b></div>`}).join('')}</div><div style="margin-top:15px"><span class="tag">${lineup.length} titulares selecionados</span><span class="tag" style="margin-left:5px">${bench.length} reservas</span></div></div></div>`}
function openPlayer(id){let p=playerById(id);if(!p)return;modal={type:'player',id};render()}
function fixturesPage(){let matches=[];state.calendar.forEach((round,i)=>round.forEach(g=>matches.push({g,i})));let visible=matches.filter(({g,i})=>g.home===state.club||g.away===state.club);return `${header('Calendário',`${visible.filter(x=>x.g.played).length} de ${visible.length} partidas disputadas`)}<div class="card"><div class="card-head"><h2>Temporada ${state.season}</h2><span class="tag">${state.league.split('|')[1]}</span></div>${visible.map(({g,i})=>{let opp=opponentOf(g),mineHome=g.home===state.club;return `<div class="fixture"><div class="fixture-date">RODADA ${i+1}<br>${g.played?'FINALIZADO':i===state.round?'PRÓXIMA':'AGENDADO'}</div><div class="fixture-clubs">${mineHome?badge(currentClub(),'sm'):badge(opp,'sm')}<b>${mineHome?esc(currentClub().name):esc(opp.name)}</b><span style="color:#748174">×</span><b>${mineHome?esc(opp.name):esc(currentClub().name)}</b>${mineHome?badge(opp,'sm'):badge(currentClub(),'sm')}</div><span class="${g.played?'fixture-score':'tag'}">${g.played?`${g.score[0]} — ${g.score[1]}`:mineHome?'CASA':'FORA'}</span>${!g.played&&i===state.round?`<button class="btn btn-primary" onclick="playMatch()">JOGAR</button>`:''}</div>`}).join('')}</div>`}
function tablePage(){let sorted=rankTeams();return `${header('Classificação',`${state.league.split('|')[1]} · Temporada ${state.season}`)}<div class="card"><div class="card-head"><h2>Tabela do campeonato</h2><span class="tag green">${sorted.findIndex(t=>t.id===state.club)+1}º ${sorted.find(t=>t.id===state.club).name}</span></div>${leagueTable(sorted)}</div><div class="grid grid-3" style="margin-top:15px"><div class="stat-card"><div class="stat-label">LÍDER</div><div class="stat-value" style="font-size:17px">${esc(sorted[0].name)}</div><div class="stat-note good">${sorted[0].pts} pontos</div></div><div class="stat-card"><div class="stat-label">ARTILHEIRO DA LIGA</div>${leagueTopScorer()}</div><div class="stat-card"><div class="stat-label">MELHOR DEFESA</div><div class="stat-value" style="font-size:17px">${esc([...sorted].sort((a,b)=>a.ga-b.ga)[0].name)}</div><div class="stat-note">${[...sorted].sort((a,b)=>a.ga-b.ga)[0].ga} gols sofridos</div></div></div>`}
function leagueTopScorer(){let players=state.teams.flatMap(t=>t.players.map(p=>({...p,club:t.name}))).sort((a,b)=>b.goals-a.goals);return `<div class="stat-value" style="font-size:17px">${players[0]?.goals?esc(players[0].name):'—'}</div><div class="stat-note">${players[0]?.goals?players[0].goals+' gols · '+esc(players[0].club):'Gols após a primeira rodada'}</div>`}
function marketPage(){let list=state.available.filter(p=>marketTab==='all'||(marketTab==='free'?p.price<10000:p.pos===marketTab));return `${header('Transferências',`Orçamento disponível: ${money(state.budget)} · Negocie reforços para o elenco.`,`<button class="btn" onclick="openModal('finance')">FINANÇAS</button>`)}<div class="page-tabs"><button class="tab ${marketTab==='all'?'active':''}" onclick="marketTab='all';render()">Todos</button>${['GOL','ZAG','MC','MEI','ATA'].map(pos=>`<button class="tab ${marketTab===pos?'active':''}" onclick="marketTab='${pos}';render()">${pos}</button>`).join('')}<button class="tab ${marketTab==='free'?'active':''}" onclick="marketTab='free';render()">Oportunidades</button></div><div class="card"><div class="card-head"><h2>Mercado de jogadores</h2><span class="tag">${list.length} observados</span></div><div class="player-row header"><span>POS</span><span>JOGADOR</span><span>IDADE</span><span>GER</span><span>VALOR</span><span class="hide-mobile">CLUBE</span><span class="hide-mobile">AÇÃO</span></div>${list.slice(0,40).map(p=>`<div class="player-row"><span class="tag">${p.pos}</span><div><div class="player-name">${esc(p.name)}</div><div class="player-meta">Potencial ${p.potential} · ${p.age} anos</div></div><span>${p.age}</span><span class="rating">${p.ovr}</span><span>${money(p.price)}</span><span class="hide-mobile">${esc(p.club)}</span><button class="btn ${state.budget>=p.price?'btn-primary':''}" style="padding:6px 8px;font-size:9px" onclick="buyPlayer('${p.id}')">${state.budget>=p.price?'CONTRATAR':'SEM VERBA'}</button></div>`).join('')||'<div class="empty">Nenhum jogador disponível nesse filtro.</div>'}</div><p class="stat-note" style="margin:12px 4px">As negociações dependem do orçamento do clube. Jogadores gerados de forma procedural são fictícios e não representam elencos licenciados.</p>`}
function buyPlayer(id){let p=state.available.find(x=>x.id===id);if(!p)return;if(state.budget<p.price)return toast('Orçamento insuficiente para essa contratação.',true);if(state.roster.length>=25)return toast('Elenco cheio. Negocie uma saída antes de contratar.',true);let target=clubById(p.clubId);if(target){target.players=target.players.filter(x=>`m-${x.id}`!==id)}state.budget-=p.price;currentClub().budget=state.budget;state.roster.push({...p,id:p.id.replace('m-',''),apps:0,goals:0,starter:false});state.available=state.available.filter(x=>x.id!==id);state.manager.rep=Math.min(100,state.manager.rep+1);state.news.unshift({date:state.date,type:'transferência',title:`${p.name} é o novo reforço`,body:`O clube fechou a contratação do atleta por ${money(p.price)}.`});save();render();toast(`${p.name} contratado com sucesso!`)}
function inboxPage(){let messages=[...state.news.map(n=>({...n,kind:'notícia'})),...state.messages.map(m=>({...m,kind:'mensagem'}))].sort((a,b)=>b.date.localeCompare(a.date));return `${header('Central do clube','Notícias, mensagens da diretoria e acontecimentos da carreira.') }<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Caixa de entrada</h2><span class="tag">${messages.length} itens</span></div>${messages.map(m=>`<div class="inbox-item"><span class="news-kicker">${esc(m.kind)} · ${dateText(m.date)}</span><b>${esc(m.title)}</b><p>${esc(m.body)}</p>${m.action?`<button class="btn btn-primary" onclick="${m.action}">RESPONDER</button>`:''}</div>`).join('')||'<div class="empty"><div class="empty-icon">✉</div><h2>Tudo em dia</h2><p>As atualizações do seu clube aparecerão aqui.</p></div>'}</div><div class="card"><div class="card-head"><h2>Perfil do treinador</h2><span class="tag green">${esc(state.manager.experience)}</span></div><div style="display:flex;align-items:center;gap:12px;margin-bottom:19px"><div class="avatar" style="width:50px;height:50px;font-size:17px">${esc(initials(state.manager.name))}</div><div><b style="font-size:14px">${esc(state.manager.name)}</b><div class="stat-note">${esc(state.manager.nationality)} · ${state.manager.age} anos</div></div></div>${[['Reputação',state.manager.rep],['Popularidade',state.manager.popularity],['Licenças',state.manager.licenses*25]].map(([x,v])=>`<div class="bar-row" style="grid-template-columns:90px 1fr 30px"><span>${x}</span><span class="bar"><i style="width:${v}%"></i></span><b>${x==='Licenças'?state.manager.licenses:v}</b></div>`).join('')}<div class="settings-item"><div><b>Contrato atual</b><small>${state.contract.years} anos · salário ${money(state.contract.salary)}/semana</small></div><button class="btn" onclick="openModal('contract')">NEGOCIAR</button></div><div class="settings-item"><div><b>Objetivo da diretoria</b><small>${esc(state.objective)}</small></div></div><button class="btn btn-danger" style="margin-top:15px" onclick="resign()">PEDIR DEMISSÃO</button></div></div>`}
function statsPage(){let c=currentClub(),top=[...state.roster].sort((a,b)=>b.goals-a.goals)[0],apps=[...state.roster].sort((a,b)=>b.apps-a.apps)[0];return `${header('Estatísticas','Acompanhe os números da temporada e o seu legado.') }<div class="stats-row"><div class="stat-card"><div class="stat-label">JOGOS NA CARREIRA</div><div class="stat-value">${state.manager.wins+state.manager.draws+state.manager.losses}</div><div class="stat-note">${state.manager.wins}V · ${state.manager.draws}E · ${state.manager.losses}D</div></div><div class="stat-card"><div class="stat-label">TÍTULOS</div><div class="stat-value">${state.manager.titles}</div><div class="stat-note">Honrarias conquistadas</div></div><div class="stat-card"><div class="stat-label">VALOR DE MERCADO</div><div class="stat-value">${money(state.manager.rep*17500)}</div><div class="stat-note">Estimativa como treinador</div></div><div class="stat-card"><div class="stat-label">POPULARIDADE</div><div class="stat-value">${state.manager.popularity}%</div><div class="stat-note">Entre os torcedores</div></div></div><div class="grid grid-2"><div class="card"><div class="card-head"><h2>Desempenho do clube</h2><span class="tag">${esc(c.name)}</span></div><div class="bar-row"><span>Vitórias</span><span class="bar"><i style="width:${Math.min(100,c.w/Math.max(1,c.w+c.d+c.l)*100)}%"></i></span><b>${c.w}</b></div><div class="bar-row"><span>Empates</span><span class="bar"><i style="width:${Math.min(100,c.d/Math.max(1,c.w+c.d+c.l)*100)}%;background:var(--gold)"></i></span><b>${c.d}</b></div><div class="bar-row"><span>Derrotas</span><span class="bar"><i style="width:${Math.min(100,c.l/Math.max(1,c.w+c.d+c.l)*100)}%;background:var(--red)"></i></span><b>${c.l}</b></div><div class="settings-item"><div><b>Artilheiro do elenco</b><small>${esc(top?.name||'—')} · ${top?.goals||0} gols</small></div></div><div class="settings-item"><div><b>Mais utilizado</b><small>${esc(apps?.name||'—')} · ${apps?.apps||0} partidas</small></div></div></div><div class="card"><div class="card-head"><h2>Histórico da carreira</h2></div>${state.manager.history.length?state.manager.history.map(h=>`<div class="fixture"><span class="tag">${h.season}</span><div><b>${esc(h.club)}</b><div class="stat-note">${esc(h.competition)} · ${h.place}º lugar</div></div><b class="rating">${h.pts} pts</b></div>`).join(''):'<div class="empty" style="padding:28px"><div class="empty-icon">◷</div><h2>Comece sua jornada</h2><p>O histórico e os títulos aparecerão conforme você avança as temporadas.</p></div>'}</div></div>`}
function resign(){if(!confirm('Pedir demissão do clube? Você poderá escolher outro time, mas sua carreira continua.'))return;state.manager.history.push({season:state.season,club:currentClub().name,competition:state.league.split('|')[1],place:rankTeams().findIndex(t=>t.id===state.club)+1,pts:currentClub().pts});state.sacked=true;state.manager.club='Sem clube';state.messages.unshift({date:state.date,title:'Você pediu demissão',body:'A diretoria aceitou seu pedido. Escolha um novo clube para continuar a carreira.'});save();openModal('job');}
function editorPage(){return `${header('Editor de elencos','Ajuste os atributos dos atletas e salve sua base neste dispositivo.') }<div class="card"><div class="card-head"><h2>Editar elenco · ${esc(currentClub().name)}</h2><button class="btn btn-primary" onclick="save();toast('Elenco salvo no arquivo de carreira.')">SALVAR EDIÇÕES</button></div><div class="player-row header"><span>POS</span><span>JOGADOR</span><span>IDADE</span><span>GER</span><span>VALOR</span><span class="hide-mobile">POTENCIAL</span><span>EDITAR</span></div>${state.roster.map(p=>`<div class="player-row"><span class="tag">${p.pos}</span><div class="player-name">${esc(p.name)}</div><span>${p.age}</span><span class="rating">${p.ovr}</span><span>${money(p.value)}</span><span class="hide-mobile">${p.potential}</span><button class="btn" style="padding:6px 8px;font-size:9px" onclick="openPlayer('${p.id}')">EDITAR</button></div>`).join('')}</div>`}
function render(){let root=document.getElementById('app');if(!state){root.innerHTML=mainMenu();return}let content=({dashboard,squad:squadPage,tactics:tacticsPage,fixtures:fixturesPage,table:tablePage,market:marketPage,inbox:inboxPage,stats:statsPage,editor:editorPage,settings:settingsPage})[route]||dashboard;root.innerHTML=`<div class="shell">${sideNav()}<main class="main">${topbar()}${content()}</main></div>${modal?modalHTML():''}`}
